UPDATE Item SET itemSlug = 'weapon', rarityID = COALESCE(NULL, rarityID), categoryID = (SELECT categoryID FROM ItemCategory WHERE categoryName = 'Weapon'), itemRequiresAttunement = 0, itemHeader = 'Weapon, Uncommon (+1), Rare (+2), or Very Rare (+3)', itemBaseRequirement = 'Any Simple or Martial', sourceID = CASE WHEN itemDescriptionSource LIKE 'SRD%' THEN (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1') ELSE sourceID END WHERE itemName = 'Weapon' COLLATE NOCASE AND itemSlug IS NULL;
INSERT INTO ItemVariant (itemID, variantName, rarityID, sortOrder) SELECT itemID, 'Weapon +1', (SELECT rarityID FROM Rarity WHERE rarityName = 'Uncommon'), 1 FROM Item WHERE itemSlug = 'weapon';
INSERT INTO ItemVariant (itemID, variantName, rarityID, sortOrder) SELECT itemID, 'Weapon +2', (SELECT rarityID FROM Rarity WHERE rarityName = 'Rare'), 2 FROM Item WHERE itemSlug = 'weapon';
INSERT INTO ItemVariant (itemID, variantName, rarityID, sortOrder) SELECT itemID, 'Weapon +3', (SELECT rarityID FROM Rarity WHERE rarityName = 'Very Rare'), 3 FROM Item WHERE itemSlug = 'weapon';
UPDATE Item SET itemSlug = 'weapon-of-warning', rarityID = COALESCE((SELECT rarityID FROM Rarity WHERE rarityName = 'Uncommon'), rarityID), categoryID = (SELECT categoryID FROM ItemCategory WHERE categoryName = 'Weapon'), itemRequiresAttunement = 1, itemHeader = 'Weapon, Uncommon (Requires Attunement)', itemBaseRequirement = 'Any Simple or Martial', sourceID = CASE WHEN itemDescriptionSource LIKE 'SRD%' THEN (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1') ELSE sourceID END WHERE itemName = 'Weapon of Warning' COLLATE NOCASE AND itemSlug IS NULL;
